import sys
sys.path.insert(0, "register/work")
from q5_lib import nd

CH13 = "Chapter 13 case administration"
nd("US:11 USC 1302", CH13 + ": the standing trustee's duties, including support-claim notices; a creditor's immunity for giving a support-claim holder the debtor's address does not change any settlement step.")
nd("US:11 USC 1303", CH13 + ": gives the debtor the trustee's use, sale and lease powers; the landlord's position is stated in the chapter 13 rules (US:11USC1327-plan-binds).")
nd("US:11 USC 1304", CH13 + ": a self-employed debtor may operate its business.")
nd("US:11 USC 1307", CH13 + ": the debtor's right to convert or dismiss at any time and the grounds for conversion or dismissal on request; the effects on the balance and refund are proposed at 348 and 349 (US:11USC348-conversion, US:11USC349-dismissal).")
nd("US:11 USC 1308", CH13 + ": the debtor's duty to file pre-petition tax returns.")
nd("US:11 USC 1321", CH13 + ": the debtor files a plan; timing is FRBP 3015(b), used in US:FRBP3015-plan-objection.")
nd("US:11 USC 1323", CH13 + ": pre-confirmation modification by the debtor; the landlord's objection route is US:FRBP3015-plan-objection.")
nd("US:11 USC 1324", CH13 + ": confirmation hearing held 20 to 45 days after the 341 meeting, and any party may object; the objection deadline the landlord meets is proposed at FRBP 3015 (US:FRBP3015-plan-objection).")
nd("US:11 USC 1329", CH13 + ": post-confirmation modification; a modified plan binds the landlord as the original does (US:11USC1327-plan-binds), and objections follow US:FRBP3015-plan-objection.")
nd("US:11 USC 1330", CH13 + ": revocation of confirmation obtained by fraud within 180 days; a remedy of plan administration that changes no settlement step.")
